mapper.select:
SELECT id, payment_no, order_id, user_id, amount, pay_type, status, pay_method, pay_time, create_time, update_time
FROM payment
WHERE id = #{id}

SELECT id, payment_no, order_id, user_id, amount, pay_type, status, pay_method, pay_time, create_time, update_time
FROM payment
WHERE payment_no = #{paymentNo}

mapper.update:
UPDATE payment
SET status = #{status}, pay_time = CASE WHEN #{status} = 'SUCCESS' THEN NOW() ELSE pay_time END
WHERE id = #{id}

UPDATE payment
SET status = #{status}, pay_time = CASE WHEN #{status} = 'SUCCESS' THEN NOW() ELSE pay_time END
WHERE payment_no = #{paymentNo}
